const data = $input.first().json;
const specs = data.specs || [];
const alertas = specs.map(s => ({
  tipo: 'cypress',
  spec: s.spec ? s.spec.split('/').pop().split('\\').pop() : 'desconocido',
  fallos: s.fallos || 0,
  tests: (s.tests || []).map(t => ({
    titulo: t.titulo || t.title || '',
    error: String(t.error || '').substring(0, 200)
  }))
}));
return [{
  json: {
    fuente: 'cypress',
    icono: '🔴',
    titulo: 'FALLO CRÍTICO EN TEST',
    alertas,
    total: data.total_fallos_criticos || specs.length || 0,
    timestamp: data.timestamp || new Date().toISOString(),
    ambiente: data.ambiente || 'QA'
  }
}];

const data = $input.first().json;
const issues = data.issues || [];
const alertas = issues.map(issue => ({
  id: issue.key,
  titulo: issue.fields?.summary || 'Sin título',
  prioridad: issue.fields?.priority?.name || 'Highest',
  estado: issue.fields?.status?.name || 'N/A',
  reportadoPor: issue.fields?.reporter?.displayName || 'Desconocido',
  asignado: issue.fields?.assignee?.displayName || 'Sin asignar',
  created: issue.fields?.created || new Date().toISOString()
}));
return [{
  json: {
    fuente: 'jira',
    icono: '🚨',
    titulo: 'BUG HIGHEST EN JIRA',
    alertas,
    total: issues.length,
    timestamp: new Date().toISOString(),
    ambiente: 'QA'
  }
}];

const data = $input.first().json;
const ahora = new Date(data.timestamp);
const hora = ahora.toLocaleTimeString('es-CL', { timeZone: 'America/Santiago', hour: '2-digit', minute: '2-digit' });
const fecha = ahora.toLocaleDateString('es-CL', { timeZone: 'America/Santiago' });

let mensajeWA = '';
let htmlEmail = '';
let asunto = '';

if (data.fuente === 'cypress') {
  const item = data.alertas[0] || {};
  const test = (item.tests || [])[0] || {};
  mensajeWA = `${data.icono} FALLO CRÍTICO QA — Bupa Chile\n\n📁 Spec: ${item.spec || 'N/A'}\n❌ Test: ${test.titulo || 'N/A'}\n⚠️ Error: ${test.error || 'Ver logs'}\n🕐 Hora: ${hora} hrs | Ambiente: QA\n\nRevisar inmediatamente.`;
  htmlEmail = `<h2 style="color:#c0392b;font-family:Arial">🔴 Fallo Crítico QA — Bupa Chile</h2><table style="border-collapse:collapse;width:100%;font-family:Arial"><tr><td style="padding:8px;background:#f8d7da"><b>Spec:</b></td><td style="padding:8px">${item.spec}</td></tr><tr><td style="padding:8px;background:#f8d7da"><b>Test:</b></td><td style="padding:8px">${test.titulo}</td></tr><tr><td style="padding:8px;background:#f8d7da"><b>Error:</b></td><td style="padding:8px;font-family:monospace;color:#c0392b">${test.error}</td></tr><tr><td style="padding:8px;background:#f8d7da"><b>Hora:</b></td><td style="padding:8px">${hora} hrs — ${fecha}</td></tr></table><p style="font-family:Arial;color:#666;margin-top:16px">Mensaje automático — QA Bupa Chile</p>`;
  asunto = `🔴 Fallo Crítico QA — ${item.spec || 'spec'} — ${hora} hrs`;
} else {
  const lineas = data.alertas.map(a => `🎫 ${a.id}: ${a.titulo}\n   👤 ${a.reportadoPor} → ${a.asignado}`).join('\n\n');
  mensajeWA = `${data.icono} BUG HIGHEST — Bupa Chile QA\n\n${lineas}\n\n🕐 Detectado: ${hora} hrs\n\nAsignar y atender de inmediato.`;
  const tarjetas = data.alertas.map(a => `<div style="border-left:4px solid #e67e22;padding:12px;margin:8px 0;font-family:Arial"><p style="margin:0"><b>${a.id}:</b> ${a.titulo}</p><p style="margin:4px 0;color:#666">Reportado por: ${a.reportadoPor} → <b>${a.asignado}</b></p></div>`).join('');
  htmlEmail = `<h2 style="color:#e67e22;font-family:Arial">🚨 Bug Highest Detectado — Bupa Chile QA</h2>${tarjetas}<p style="font-family:Arial;color:#666;margin-top:16px">Detectado a las ${hora} hrs — ${fecha}</p>`;
  asunto = `🚨 ${data.total} Bug(s) Highest — Bupa Chile QA — ${hora} hrs`;
}

return [{ json: { mensajeWA: encodeURIComponent(mensajeWA), htmlEmail, asunto, fuente: data.fuente } }];
